import React, { useState, useEffect } from "react";
import TaskList from "./components/TaskList";
import api from "./services/api";

interface Task{
    id: number;
    text: string;
    priority: "High" | "Medium" | "Low";
    doneFlag: boolean;
    dueDate?: string;
    creationDate: string;
}

const App: React.FC = () => {
    const[tasks, setTasks] = useState<Task[]>([]);

    const fetchTasks = async (filteredTasks?: Task[]) => {

        if(filteredTasks){
            setTasks(filteredTasks);
            return;
        }

        try{
            const response = await api.get<Task[]>("/tasks");
            setTasks(response.data);
        }catch(error){
            console.error("Error getting tasks", error);
        }
    };

    useEffect(() => {
        fetchTasks();
    }, []);

    const markTaskAsDone = async (id: number) => {

        try{
            const taskToUpdate = tasks.find((task) => task.id === id);
            if(!taskToUpdate) return;

            const isDone = taskToUpdate.doneFlag;

            if(isDone){
                await api.put(`/tasks/${id}/undone`);
            }else{
                await api.post(`/tasks/${id}/done`);
            }

            setTasks((prevTasks) =>
                prevTasks.map((task) =>
                    task.id === id ? { ...task, doneFlag: !task.doneFlag } : task
                )
            );
        }catch(error){
            console.error("Error marking task as done", error);
        }
    };

    return (
        <div>
            <h1>To-Do App</h1>
            <TaskList
                tasks = {tasks}
                markTaskAsDone = {markTaskAsDone}
                onTaskAdded = {fetchTasks}
                onTaskUpdated = {fetchTasks}
                onTaskDeleted = {fetchTasks}
                fetchTasks = {fetchTasks}
            />
        </div>
    );
};

export default App;
